from collections import defaultdict
class Solution:
    def calcEquation(self, equations, values, queries):
        g=defaultdict(list)
        for (a,b),v in zip(equations,values):
            g[a].append((b,v));g[b].append((a,1.0/v))
        def dfs(a,b,seen):
            if a==b:return 1.0
            seen.add(a)
            for nxt,w in g[a]:
                if nxt not in seen:
                    result=dfs(nxt,b,seen)
                    if result!=-1.0:return w*result
            return -1.0
        out=[]
        for a,b in queries:
            out.append(dfs(a,b,set()) if a in g and b in g else -1.0)
        return out

import java.util.*;
class Solution {
    public double[] calcEquation(List<List<String>> equations,double[] values,List<List<String>> queries) {
        Map<String,List<Object[]>> graph=new HashMap<>();
        for(int i=0;i<equations.size();i++){
            String a=equations.get(i).get(0),b=equations.get(i).get(1);double v=values[i];
            graph.computeIfAbsent(a,k->new ArrayList<>()).add(new Object[]{b,v});
            graph.computeIfAbsent(b,k->new ArrayList<>()).add(new Object[]{a,1.0/v});
        }
        double[] out=new double[queries.size()];
        for(int i=0;i<queries.size();i++){
            String a=queries.get(i).get(0),b=queries.get(i).get(1);
            out[i]=graph.containsKey(a)&&graph.containsKey(b)?dfs(a,b,new HashSet<>(),1.0,graph):-1.0;
        }
        return out;
    }
    private double dfs(String a,String b,Set<String> seen,double product,Map<String,List<Object[]>> graph){
        if(a.equals(b))return product;seen.add(a);
        for(Object[] e:graph.get(a)){
            String next=(String)e[0];
            if(!seen.contains(next)){double r=dfs(next,b,seen,product*(double)e[1],graph);if(r!=-1.0)return r;}
        }
        return -1.0;
    }
}

class Solution:
    def findNthDigit(self, n: int) -> int:
        length=1;count=9;start=1
        while n>length*count:
            n-=length*count;length+=1;count*=10;start*=10
        number=start+(n-1)//length
        return int(str(number)[(n-1)%length])

class Solution {
    public int findNthDigit(int n) {
        long pos=n,len=1,count=9,start=1;
        while(pos>len*count){pos-=len*count;len++;count*=10;start*=10;}
        long num=start+(pos-1)/len;int idx=(int)((pos-1)%len);
        return Long.toString(num).charAt(idx)-'0';
    }
}

