import java.util.*;
class Solution {
    public List<String> readBinaryWatch(int turnedOn) {
        List<String> out=new ArrayList<>();
        for(int h=0;h<12;h++)for(int m=0;m<60;m++)if(Integer.bitCount(h)+Integer.bitCount(m)==turnedOn)out.add(String.format("%d:%02d",h,m));
        return out;
    }
}

class Solution:
    def removeKdigits(self, num: str, k: int) -> str:
        stack=[]
        for c in num:
            while k and stack and stack[-1]>c:
                stack.pop();k-=1
            stack.append(c)
        if k:stack=stack[:-k]
        return ''.join(stack).lstrip('0') or '0'

class Solution {
    public String removeKdigits(String num,int k) {
        char[] st=new char[num.length()];int top=0;
        for(char c:num.toCharArray()){while(k>0&&top>0&&st[top-1]>c){top--;k--;}st[top++]=c;}
        top=Math.max(0,top-k);int i=0;while(i<top&&st[i]=='0')i++;return i==top?"0":new String(st,i,top-i);
    }
}

class Solution:
    def canCross(self, stones: list[int]) -> bool:
        if len(stones)<2:return True
        if stones[1]!=1:return False
        positions=set(stones);jumps={x:set() for x in stones};jumps[0].add(0)
        for x in stones:
            for k in jumps[x]:
                for step in (k-1,k,k+1):
                    if step>0 and x+step in positions:jumps[x+step].add(step)
        return bool(jumps[stones[-1]])

import java.util.*;
class Solution {
    public boolean canCross(int[] stones) {
        if(stones.length<2)return true;if(stones[1]!=1)return false;
        Map<Integer,Set<Integer>> jumps=new HashMap<>();for(int x:stones)jumps.put(x,new HashSet<>());jumps.get(0).add(0);
        for(int x:stones)for(int k:new ArrayList<>(jumps.get(x)))for(int d=k-1;d<=k+1;d++)if(d>0&&jumps.containsKey(x+d))jumps.get(x+d).add(d);
        return !jumps.get(stones[stones.length-1]).isEmpty();
    }
}

class Solution:
    def sumOfLeftLeaves(self, root) -> int:
        if not root:return 0
        total=0
        if root.left:
            if not root.left.left and not root.left.right:total+=root.left.val
            else:total+=self.sumOfLeftLeaves(root.left)
        total+=self.sumOfLeftLeaves(root.right)
        return total

class Solution {
    public int sumOfLeftLeaves(TreeNode root) {
        if(root==null)return 0;int sum=0;
        if(root.left!=null){if(root.left.left==null&&root.left.right==null)sum+=root.left.val;else sum+=sumOfLeftLeaves(root.left);}
        sum+=sumOfLeftLeaves(root.right);return sum;
    }
}

class Solution:
    def toHex(self, num: int) -> str:
        if num==0:return "0"
        num &= 0xffffffff
        digits="0123456789abcdef";out=[]
        while num:
            out.append(digits[num&15]);num>>=4
        return ''.join(reversed(out))

class Solution {
    public String toHex(int num) {
        if(num==0)return "0";char[]digits="0123456789abcdef".toCharArray();StringBuilder out=new StringBuilder();
        while(num!=0){out.append(digits[num&15]);num>>>=4;}return out.reverse().toString();
    }
}

class Solution:
    def reconstructQueue(self, people: list[list[int]]) -> list[list[int]]:
        people.sort(key=lambda p:(-p[0],p[1]));out=[]
        for person in people:out.insert(person[1],person)
        return out

import java.util.*;
class Solution {
    public int[][] reconstructQueue(int[][] people) {
        Arrays.sort(people,(a,b)->a[0]!=b[0]?Integer.compare(b[0],a[0]):Integer.compare(a[1],b[1]));
        List<int[]> out=new ArrayList<>();for(int[]p:people)out.add(p[1],p);
        return out.toArray(new int[people.length][]);
    }
}

import heapq
class Solution:
    def trapRainWater(self, heightMap: list[list[int]]) -> int:
        if len(heightMap)<3 or len(heightMap[0])<3:return 0
        m,n=len(heightMap),len(heightMap[0]);seen=[[False]*n for _ in range(m)];heap=[]
        for r in range(m):
            for c in (0,n-1):
                heapq.heappush(heap,(heightMap[r][c],r,c));seen[r][c]=True
        for c in range(1,n-1):
            for r in (0,m-1):
                heapq.heappush(heap,(heightMap[r][c],r,c));seen[r][c]=True
        water=0
        while heap:
            h,r,c=heapq.heappop(heap)
            for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                nr,nc=r+dr,c+dc
                if 0<=nr<m and 0<=nc<n and not seen[nr][nc]:
                    seen[nr][nc]=True;nh=heightMap[nr][nc]
                    water+=max(0,h-nh);heapq.heappush(heap,(max(h,nh),nr,nc))
        return water

import java.util.*;
class Solution {
    public int trapRainWater(int[][] h) {
        int m=h.length,n=h[0].length;if(m<3||n<3)return 0;
        boolean[][]seen=new boolean[m][n];PriorityQueue<int[]>pq=new PriorityQueue<>(Comparator.comparingInt(a->a[0]));
        for(int r=0;r<m;r++){add(pq,seen,h,r,0);add(pq,seen,h,r,n-1);}
        for(int c=1;c<n-1;c++){add(pq,seen,h,0,c);add(pq,seen,h,m-1,c);}
        int water=0;int[][]d={{1,0},{-1,0},{0,1},{0,-1}};
        while(!pq.isEmpty()){int[]cur=pq.poll();for(int[]v:d){int r=cur[1]+v[0],c=cur[2]+v[1];if(r>=0&&r<m&&c>=0&&c<n&&!seen[r][c]){seen[r][c]=true;water+=Math.max(0,cur[0]-h[r][c]);pq.offer(new int[]{Math.max(cur[0],h[r][c]),r,c});}}}
        return water;
    }
    private void add(PriorityQueue<int[]>pq,boolean[][]seen,int[][]h,int r,int c){if(!seen[r][c]){seen[r][c]=true;pq.offer(new int[]{h[r][c],r,c});}}
}

from collections import Counter
class Solution:
    def longestPalindrome(self, s: str) -> int:
        counts=Counter(s);length=0;odd=False
        for n in counts.values():
            length+=(n//2)*2
            if n%2:odd=True
        return length+int(odd)

class Solution {
    public int longestPalindrome(String s) {
        int[]c=new int[128];for(char x:s.toCharArray())c[x]++;int len=0;boolean odd=false;
        for(int n:c){len+=n/2*2;if(n%2==1)odd=true;}return len+(odd?1:0);
    }
}
